from labels import label; from unittest import TestCase
import random
import string
class T(TestCase):
    def test_unicode(self):
        for _ in range(500):
            name = ''.join(random.Random(1234).choice(string.printable) for _ in range(10))
            self.assertEqual(label(name, upper=False), name)
            self.assertEqual(label(name, upper=True), name.upper())

